264.     public void visitToken(DetailAST ast) {
265.         final String line = getLine(ast.getLineNo() - 1);
266.         final int before = ast.getColumnNo() - 1;
267.         final int[] codePoints = line.codePoints().toArray();
268. 
269.         if ((before == -1 || isWhitespace(codePoints, before))
270.                 && !isInEmptyForInitializerOrCondition(ast)) {
271.             boolean flag = !allowLineBreaks;
272.             // verify all characters before '.' are whitespace
273.             for (int i = 0; i <= before - 1; i++) {
274.                 if (!isWhitespace(codePoints, i)) {
275.                     flag = true;
276.                     break;
