179.     public static int lengthMinusTrailingWhitespace(String line) {
180.         int len = line.length();
181.         for (int i = len - 1; i >= 0; i--) {
182.             if (!Character.isWhitespace(line.charAt(i))) {
183.                 break;
184.             }
185.             len--;
186.         }
