375.      * @return resolved file URI
376.      * @throws CheckstyleException on failure
377.      */
378.     private static URI getFilepathOrClasspathUri(String filename) throws CheckstyleException {
379.         final URI uri;
380.         final File file = new File(filename);
381. 
382.         if (file.exists()) {
383.             uri = file.toURI();
384.         }
385.         else {
